{
  "name": "opencode-plugin-loop",
  "version": "0.8.3",
  "description": "/loop command for opencode — run prompts on a schedule (fixed, adaptive, or maintenance), modeled after Claude Code's /loop",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./commands/loop.md": "./commands/loop.md",
    "./commands/*": "./commands/*"
  },
  "files": [
    "dist",
    "commands",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude-code",
    "loop",
    "scheduled-tasks",
    "cron",
    "ai-coding-agent"
  ],
  "license": "MIT",
  "author": {
    "name": "opencode-plugin-loop authors"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jkrandom-sudo/opencode-plugin-loop.git"
  },
  "bugs": {
    "url": "https://github.com/jkrandom-sudo/opencode-plugin-loop/issues"
  },
  "homepage": "https://github.com/jkrandom-sudo/opencode-plugin-loop#readme",
  "engines": {
    "node": ">=18",
    "opencode": ">=1.17.18"
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "prepare": "npm run build",
    "test": "npm run build && node --test tests/*.test.mjs",
    "dry-run": "npm publish --dry-run",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.18"
  },
  "devDependencies": {
    "@babel/core": "^7.28.0",
    "@babel/preset-typescript": "^7.27.1",
    "@opencode-ai/plugin": "^1.17.18",
    "@types/node": "^22.0.0",
    "typescript": "^5.4.0"
  },
  "opencode": {
    "plugin": true,
    "commands": [
      "commands/loop.md",
      "commands/proactive.md"
    ]
  }
}
